CREATE OR REPLACE FUNCTION public.finance_account_redirect_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (TG_OP='INSERT' AND NEW.future_account_id IS NOT NULL) OR (TG_OP='UPDATE' AND NEW.future_account_id IS DISTINCT FROM OLD.future_account_id) THEN IF current_setting('finance.account_redirect_source',true) IS DISTINCT FROM NEW.id::text THEN RAISE EXCEPTION 'Use the guarded account merge';END IF;IF NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE id=NEW.future_account_id AND tenant_id=NEW.tenant_id AND account_type=NEW.account_type AND normal_side=NEW.normal_side AND is_active AND future_account_id IS NULL) THEN RAISE EXCEPTION 'Compatible same-tenant target required';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER account_redirect_guard BEFORE INSERT OR UPDATE OF future_account_id ON public.chart_of_accounts FOR EACH ROW EXECUTE FUNCTION public.finance_account_redirect_guard();
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_account_merge(uuid,uuid,uuid,date,boolean)'::regprocedure) INTO def;def:=replace(def,'UPDATE chart_of_accounts SET future_account_id=target','PERFORM set_config(''finance.account_redirect_source'',source::text,true);UPDATE chart_of_accounts SET future_account_id=target');def:=replace(def,'RETURN q;','PERFORM set_config(''finance.account_redirect_source'','''',true);RETURN q;');EXECUTE def;END $$;
CREATE OR REPLACE FUNCTION public.finance_future_account_line() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE dest uuid;BEGIN IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM journal_entries WHERE id=OLD.entry_id AND status='posted') THEN RETURN NEW;END IF;IF coalesce(current_setting('finance.keep_reclass_accounts',true),'')='yes' THEN RETURN NEW;END IF;SELECT a.future_account_id INTO dest FROM chart_of_accounts a JOIN chart_of_accounts b ON b.id=a.future_account_id AND b.tenant_id=a.tenant_id AND b.account_type=a.account_type AND b.normal_side=a.normal_side AND b.is_active WHERE a.id=NEW.account_id AND a.tenant_id=NEW.tenant_id;IF dest IS NOT NULL THEN NEW.account_id:=dest;END IF;RETURN NEW;END $$;